package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Persistence goes through systemd-networkd, which owns the interfaces
// (netplan generates the base files into /run/systemd/network). We add a
// drop-in next to each generated file, so netplan stays the base layer and
// `netplan generate` does not lose our settings. What networkd cannot
// express (link speed, port description, mirroring) is reapplied by the
// daemon itself at startup from the saved config.

const dropinName = "50-napi-switchd.conf"

type Paths struct {
	Config    string // saved config JSON
	NetDir    string // where drop-in directories are created (/etc/systemd/network)
	NetSearch []string
	RunNetDir string // runtime networkd files (/run/systemd/network)
	FWFile    string // loaded nft script (/run/napi-switch/firewall.nft)
}

// findUnit returns the basename of the networkd file matching an interface,
// e.g. 10-netplan-lan1.network. kind is "network" or "netdev".
func findUnit(search []string, kind, ifname string) string {
	for _, d := range search {
		files, _ := filepath.Glob(filepath.Join(d, "*."+kind))
		sort.Strings(files)
		for _, f := range files {
			if strings.Contains(filepath.Base(f), "napi-switchd") {
				continue // our own L3 units, not a base to attach drop-ins to
			}
			if unitNames(f, kind)[ifname] {
				return filepath.Base(f)
			}
		}
	}
	return ""
}

func unitNames(file, kind string) map[string]bool {
	fh, err := os.Open(file)
	if err != nil {
		return nil
	}
	defer fh.Close()
	want := map[string]string{"network": "[Match]", "netdev": "[NetDev]"}[kind]
	names := map[string]bool{}
	sec := ""
	sc := bufio.NewScanner(fh)
	for sc.Scan() {
		l := strings.TrimSpace(sc.Text())
		if strings.HasPrefix(l, "[") {
			sec = l
			continue
		}
		if k, v, ok := strings.Cut(l, "="); ok && sec == want && strings.TrimSpace(k) == "Name" {
			for _, n := range strings.Fields(v) {
				names[n] = true
			}
		}
	}
	return names
}

func yesno(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

const dropinHeader = "# Generated by napi-switchd from %s - do not edit, use the API.\n"

// RenderDropins returns drop-in path (relative to NetDir) -> content.
func RenderDropins(c *Config, bridge string, unit func(kind, ifname string) string, cfgPath string) map[string]string {
	files := map[string]string{}
	b := c.Bridge
	var s strings.Builder
	fmt.Fprintf(&s, dropinHeader, cfgPath)
	// MRP needs mrp_server and napi-switchd, which start after networkd has
	// brought the ring ports up: boot with STP so a closed ring is never a
	// loop, the daemon then swaps STP for MRP (secondary port held down).
	stp := b.STP.Enabled || c.MRP != nil
	fmt.Fprintf(&s, "\n[Bridge]\nVLANFiltering=%s\nSTP=%s\nPriority=%d\nHelloTimeSec=%d\nForwardDelaySec=%d\nMaxAgeSec=%d\nAgeingTimeSec=%d\nMulticastSnooping=%s\nMulticastQuerier=%s\n",
		yesno(b.VLANAware), yesno(stp), b.STP.Priority, b.STP.HelloTime, b.STP.ForwardDelay, b.STP.MaxAge,
		b.AgeingTime, yesno(b.IGMP.Snooping), yesno(b.IGMP.Querier))
	if b.VLANAware {
		// No implicit VLAN 1 on every port: membership is fully explicit.
		s.WriteString("DefaultPVID=none\n")
	}
	put := func(u, content string) {
		if u != "" {
			files[u+".d/"+dropinName] = content
		}
	}
	put(unit("netdev", bridge), s.String())

	s.Reset()
	fmt.Fprintf(&s, dropinHeader, cfgPath)
	if b.VLANAware {
		fmt.Fprintf(&s, "\n[BridgeVLAN]\nVLAN=%d\nPVID=%d\nEgressUntagged=%d\n", b.MgmtVLAN, b.MgmtVLAN, b.MgmtVLAN)
	}
	put(unit("network", bridge), s.String())

	for _, n := range c.PortNames() {
		p := c.Ports[n]
		s.Reset()
		fmt.Fprintf(&s, dropinHeader, cfgPath)
		policy := "down"
		if p.Enabled {
			policy = "up"
		}
		fmt.Fprintf(&s, "\n[Link]\nActivationPolicy=%s\n", policy)
		fmt.Fprintf(&s, "\n[Bridge]\nPriority=%d\nLearning=%s\nIsolated=%s\n", p.STPPriority, yesno(p.Learning), yesno(p.Isolated))
		if p.STPCost > 0 {
			fmt.Fprintf(&s, "Cost=%d\n", p.STPCost)
		}
		if b.VLANAware {
			if p.PVID > 0 {
				fmt.Fprintf(&s, "\n[BridgeVLAN]\nVLAN=%d\nPVID=%d\nEgressUntagged=%d\n", p.PVID, p.PVID, p.PVID)
			}
			for _, t := range p.Tagged {
				fmt.Fprintf(&s, "\n[BridgeVLAN]\nVLAN=%d\n", t)
			}
		}
		for _, e := range c.StaticFDB {
			if e.Port != n {
				continue
			}
			fmt.Fprintf(&s, "\n[BridgeFDB]\nMACAddress=%s\nAssociatedWith=master\n", e.MAC)
			if e.VLAN > 0 {
				fmt.Fprintf(&s, "VLANId=%d\n", e.VLAN)
			}
		}
		// Ports without a networkd file of their own (sfp, not in netplan) are
		// left alone: there is nothing to attach a drop-in to.
		if u := unit("network", n); u != "" {
			put(u, s.String())
			files[linkFileName(n)] = renderLink(n, p, cfgPath)
		}
	}
	return files
}

// linkFileName is our systemd .link file for a switch port.
func linkFileName(port string) string { return "10-napi-switchd-" + port + ".link" }

// renderLink sets 802.3x pause as udev brings the port up, before its link
// does (napi-switchd starts later). One .link file applies per device, so it
// repeats 99-default.link's policies. Off is forced ("autoneg" off too):
// phylink boots with pause advertised while reporting it off, and udev
// skips a setting equal to the current one.
func renderLink(port string, p *Port, cfgPath string) string {
	var s strings.Builder
	fmt.Fprintf(&s, dropinHeader, cfgPath)
	fmt.Fprintf(&s, "\n[Match]\nOriginalName=%s\nDriver=dsa\n", port)
	s.WriteString("\n[Link]\nNamePolicy=keep kernel database onboard slot path\n" +
		"AlternativeNamesPolicy=database onboard slot path mac\nMACAddressPolicy=persistent\n")
	v := yesno(p.FlowControl)
	fmt.Fprintf(&s, "AutoNegotiationFlowControl=%s\nRxFlowControl=%s\nTxFlowControl=%s\n", v, v, v)
	return s.String()
}

func writeAtomic(path string, data []byte, mode os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), mode); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

// SaveConfig writes the config file and all networkd drop-ins. Stale
// drop-ins of ours (e.g. for a renamed interface) are removed.
func SaveConfig(c *Config, p Paths, bridge string) ([]string, error) {
	unit := func(kind, ifname string) string { return findUnit(p.NetSearch, kind, ifname) }
	files := RenderDropins(c, bridge, unit, p.Config)
	var written []string
	for rel, content := range files {
		path := filepath.Join(p.NetDir, rel)
		if err := writeAtomic(path, []byte(content), 0o644); err != nil {
			return written, err
		}
		written = append(written, path)
	}
	old, _ := filepath.Glob(filepath.Join(p.NetDir, "*.d", dropinName))
	links, _ := filepath.Glob(filepath.Join(p.NetDir, linkFileName("*")))
	old = append(old, links...)
	for _, f := range old {
		rel, _ := filepath.Rel(p.NetDir, f)
		if _, ok := files[rel]; !ok {
			_ = os.Remove(f)
		}
	}
	nw, err := saveNetwork(c, p, bridge)
	written = append(written, nw...)
	if err != nil {
		return written, err
	}
	data, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return written, err
	}
	if err := writeAtomic(p.Config, append(data, '\n'), 0o644); err != nil {
		return written, err
	}
	sort.Strings(written)
	return append(written, p.Config), nil
}

func LoadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var c Config
	if err := json.Unmarshal(data, &c); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	c.Normalize()
	return &c, nil
}
